 static String time(long ms){long seconds=Math.max(0,ms)/1000;return seconds>=3600?String.format(java.util.Locale.ROOT,"%d:%02d:%02d",seconds/3600,seconds/60%60,seconds%60):String.format(java.util.Locale.ROOT,"%d:%02d",seconds/60,seconds%60);}
 void refresh(){if(closed||player.closed)return;long position=player.engine==null?0:Math.max(0,player.engine.getTime()),length=player.engine==null?0:player.engine.getLength();int shown=player.media==null||player.media.getStats()==null?0:player.media.getStats().displayedPictures;long now=SystemClock.elapsedRealtime();if(shown!=lastShown){lastShown=shown;lastPictureAt=now;}boolean failed=player.state.startsWith("Source failed"),waiting=!player.paused&&!player.ended&&!failed&&(shown==0||player.state.equals("Buffering")||now-lastPictureAt>8000);loading.setVisibility(waiting||failed||player.ended?View.VISIBLE:View.GONE);spinner.setVisibility(waiting?View.VISIBLE:View.GONE);if(a.autoNext==null){loadingTitle.setText(failed?"Unable to play this stream":player.ended?"Finished":shown>0?"Buffering…":"Loading video…");loadingNote.setText(failed?"Choose Sources to try another stream":player.ended?"Choose Sources or press Back":player.openedAt>0&&now-player.openedAt>15000?"Still waiting · you can choose another source":shown>0?"Waiting for more video":"Connecting and preparing the video");}state.setText(failed?"Playback failed":player.ended?"Finished":player.paused?"Paused":waiting?"Loading…":"Playing");play.setText(player.paused||player.ended?"▶":"Ⅱ");play.setContentDescription(player.paused?"Play":"Pause");elapsed.setText(time(position));remaining.setText(length>0?"−"+time(length-position):"--:--");timeline.setEnabled(length>0&&player.engine!=null&&player.engine.isSeekable());if(!timeline.isPressed())timeline.setProgress(length>0?(int)Math.min(1000,position*1000/length):0);if(player.paused||failed||player.ended){if(controls.getVisibility()!=View.VISIBLE){controls.setVisibility(View.VISIBLE);play.requestFocus();}}}
 final Runnable update=new Runnable(){public void run(){if(closed)return;refresh();clock.postDelayed(this,250);}};
